import asyncio,json
from datetime import datetime,timezone
from pathlib import Path
from types import SimpleNamespace
from friday_chat.commands.memory import insights_handler,summaries_handler,meta_handler
from friday_chat.memory_views import MemoryCollection,MemoryRecordKind,MemoryRecordQueryResult,MemoryRecordView
s=Path(__file__).parent;events=[]
class UnusedDate(datetime):
 def isoformat(self,*args,**kwargs):
  events.append('UNUSED isoformat');raise RuntimeError('unused metadata evaluated')
class TracedDate(datetime):
 def isoformat(self,*args,**kwargs):
  events.append('format created_at');return super().isoformat(*args,**kwargs)
class TracedFloat(float):
 def __new__(cls,value,label):
  obj=super().__new__(cls,value);obj.label=label;return obj
 def __format__(self,spec):
  events.append('format '+self.label);return super().__format__(spec)
fields=set(MemoryRecordView.__dataclass_fields__)
class Row(MemoryRecordView):
 def __getattribute__(self,name):
  if name in fields:events.append('read '+name)
  return super().__getattribute__(name)
class Incomplete(MemoryRecordQueryResult):
 @property
 def complete(self):
  events.append('read complete');return False
async def observe(handler,kind,row=None,incomplete=False):
 events.clear()
 result=Incomplete(kind,()) if incomplete else MemoryRecordQueryResult(kind,(row,))
 class Port:
  async def query_memory_records(self,requested):
   events.append('query '+requested.value);return result
 ctx=SimpleNamespace(runtime=SimpleNamespace(memory=Port()))
 out=await handler(ctx,(),None)
 return {'output':out.output,'events':list(events)}
async def main():
 rows={}
 for name,handler,kind in [('insights',insights_handler,MemoryRecordKind.INSIGHT),('summaries',summaries_handler,MemoryRecordKind.SUMMARY)]:
  row=Row('id',kind,'text',MemoryCollection.SHORT_TERM,created_at=UnusedDate(2025,1,1))
  a=await observe(handler,kind,row)
  if a['events']!=['query '+kind.value,'read text']:raise RuntimeError('Plain record now reads metadata')
  rows[name+'-unused-metadata']=a
 row=Row('id',MemoryRecordKind.META_INSIGHT,'text',MemoryCollection.SHORT_TERM,created_at=TracedDate(2025,1,1,tzinfo=timezone.utc),confidence=TracedFloat(.8,'confidence'),verification_confidence=TracedFloat(.9,'verification_confidence'))
 a=await observe(meta_handler,MemoryRecordKind.META_INSIGHT,row);order=['format verification_confidence','read text','format created_at','format confidence']
 if [a['events'].index(x) for x in order]!=sorted(a['events'].index(x) for x in order):raise RuntimeError('Unexpected meta evaluation order')
 rows['meta-evaluation-order']=a
 a=await observe(meta_handler,MemoryRecordKind.META_INSIGHT,incomplete=True)
 if not a['output'].startswith('Meta insight query incomplete;') or a['events']!=['query meta_insight','read complete']:raise RuntimeError('Incomplete flag behavior not observed')
 rows['meta-incomplete-no-warnings']=a
 proof={'kind':'planning-only actual legacy characterization, not proposed implementation','source_revision':'c5871054266da2340486d2043062c5fb95611c00','current_product_bytes_unchanged':True,'cases':rows,'application_network_or_real_store_calls':False}
 (s/'record-characterization.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps(proof,indent=2))
asyncio.run(main())

